/* Card set: Stardew Valley (generated from the approved roster.csv by the Stardew build, schema per tools/csv-to-set.js).
   (stardew-valley.js exceeds the comfortable push size, so the remaining cards live in
   stardew-valley-additions.js, which must stay directly after 'stardew-valley.js' in sets/manifest.js.) */
CardSets.register({"id":"stardew-valley","name":"Stardew Valley","code":"STAR","description":"420 cards from the valley — its villagers, fish, crops, cooking, monsters and festivals, from Abigail and the Junimos to the Legend in the mountain lake. Time to tend the farm.","theme":{"primary":"#4a7c2f","secondary":"#8a5a2b","artBackground":"#fdf6d8","artFit":"contain"},"pack":{"name":"Stardew Valley Pack","emblem":"⭐","skin":"stardew"},"cards":[{"name":"Abigail","rarity":"chase","id":"abigail","subtitle":"Villagers & NPCs","details":"Pierre and Caroline's daughter, who would rather eat an amethyst than shelve one, play flute in the rain, and practise her sword in the graveyard.","image":"https://stardewvalleywiki.com/mediawiki/images/8/88/Abigail.png"},{"name":"Sebastian","rarity":"chase","id":"sebastian","subtitle":"Villagers & NPCs","details":"Reclusive programmer in Robin's basement, happiest with sashimi, a frozen tear, his motorcycle, and Sam and Abigail at the saloon pool table.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a8/Sebastian.png"},{"name":"Krobus","rarity":"chase","id":"krobus","subtitle":"Villagers & NPCs","details":"The valley's only friendly monster: a shadow person selling rare goods in the sewers, fond of void eggs, and able to move in as a roommate.","image":"https://stardewvalleywiki.com/mediawiki/images/7/71/Krobus.png"},{"name":"Junimo","rarity":"chase","id":"junimo","subtitle":"Villagers & NPCs","details":"Forest spirits who restore the Community Center through bundles, then help on the farm from a hut, turning rainbow if given a prismatic shard.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/Junimo.gif"},{"name":"Mr. Qi","rarity":"chase","id":"mr-qi","subtitle":"Villagers & NPCs","details":"Mysterious patron of the Calico Desert casino and the Ginger Island walnut room, dealing in Qi coins, Qi gems, and impossibly demanding quests.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b4/Mr._Qi.png"},{"name":"Alex","rarity":"legendary","id":"alex","subtitle":"Villagers & NPCs","details":"George and Evelyn's grandson, a would-be gridball star who trains in town, works out at the spa, and loves a complete breakfast or salmon dinner.","image":"https://stardewvalleywiki.com/mediawiki/images/0/04/Alex.png"},{"name":"Elliott","rarity":"legendary","id":"elliott","subtitle":"Villagers & NPCs","details":"Romantic writer in a beach cabin south of town, working on his novel between crab cakes, lobster, pomegranates, and chats with Willy and Leah.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bd/Elliott.png"},{"name":"Emily","rarity":"legendary","id":"emily","subtitle":"Villagers & NPCs","details":"Haley's older sister at 2 Willow Lane, who works at the saloon, sews and dyes clothes, and loves cloth and almost every bright gemstone.","image":"https://stardewvalleywiki.com/mediawiki/images/2/28/Emily.png"},{"name":"Haley","rarity":"legendary","id":"haley","subtitle":"Villagers & NPCs","details":"Emily's younger sister, a photographer who loves coconut, pink cake, and sunflowers — and famously hates being handed a prismatic shard.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1b/Haley.png"},{"name":"Harvey","rarity":"legendary","id":"harvey","subtitle":"Villagers & NPCs","details":"Town doctor who runs the clinic with Maru, frets over everyone's health and his radio hobby, and perks up instantly for coffee or wine.","image":"https://stardewvalleywiki.com/mediawiki/images/9/95/Harvey.png"},{"name":"Leah","rarity":"legendary","id":"leah","subtitle":"Villagers & NPCs","details":"Artist in a Cindersap Forest cottage, sculpting and painting by the pond, foraging wild meals, and loving salad, goat cheese, truffles, and wine.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e6/Leah.png"},{"name":"Maru","rarity":"legendary","id":"maru","subtitle":"Villagers & NPCs","details":"Inventor and clinic nurse, daughter of Demetrius and Robin and Sebastian's half-sister, who builds gadgets and loves strawberries and battery packs.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f8/Maru.png"},{"name":"Penny","rarity":"legendary","id":"penny","subtitle":"Villagers & NPCs","details":"Kind teacher who tutors Jas and Vincent at the museum, lives in a trailer with her mother Pam, and loves melons, poppies, and sandfish.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ab/Penny.png"},{"name":"Sam","rarity":"legendary","id":"sam","subtitle":"Villagers & NPCs","details":"Skateboarding musician son of Jodi and Kent and big brother to Vincent, who works at JojaMart and loves pizza, maple bars, and cactus fruit.","image":"https://stardewvalleywiki.com/mediawiki/images/9/94/Sam.png"},{"name":"Shane","rarity":"legendary","id":"shane","subtitle":"Villagers & NPCs","details":"Marnie's nephew and Jas's godfather, a JojaMart worker whose love of beer, pizza, and pepper poppers hides a soft spot for his blue chickens.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8b/Shane.png"},{"name":"Wizard","rarity":"epic","id":"wizard","subtitle":"Villagers & NPCs","details":"M. Rasmodius, the reclusive wizard in the Cindersap tower, who studies the elemental world, speaks for the Junimos, and loves purple mushrooms.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c7/Wizard.png"},{"name":"Dwarf","rarity":"epic","id":"dwarf","subtitle":"Villagers & NPCs","details":"Cheerful dwarf merchant living in the eastern Mines, speaking Dwarvish until the scrolls are translated, and loving gems and omni geodes.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ed/Dwarf.png"},{"name":"Leo","rarity":"epic","id":"leo","subtitle":"Villagers & NPCs","details":"Parrot-raised boy on Ginger Island who befriends the island birds, loves mango, duck feathers, ostrich eggs, and poi, and later visits the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1d/Leo.png"},{"name":"Lewis","rarity":"epic","id":"lewis","subtitle":"Villagers & NPCs","details":"Long-serving mayor of Pelican Town, keeper of its taxes and traditions, host of the Luau soup tasting, and a man with a famous pair of shorts.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2b/Lewis.png"},{"name":"Grandpa","rarity":"epic","id":"grandpa","subtitle":"Villagers & NPCs","details":"The farmer's late grandfather, whose letter and sealed envelope start the whole story and who returns in spirit to judge the farm in year three.","image":"https://stardewvalleywiki.com/mediawiki/images/8/88/Grandpa.png"},{"name":"Caroline","rarity":"rare","id":"caroline","subtitle":"Villagers & NPCs","details":"Pierre's wife and Abigail's mother, who sips green tea in her sunroom garden, does aerobics with friends, and loves tropical curry and fish tacos.","image":"https://stardewvalleywiki.com/mediawiki/images/8/87/Caroline.png"},{"name":"Clint","rarity":"rare","id":"clint","subtitle":"Villagers & NPCs","details":"Blacksmith east of town who cracks geodes, upgrades tools, and forges rings, living above the shop and loving gems, omni geodes, and artichoke dip.","image":"https://stardewvalleywiki.com/mediawiki/images/3/31/Clint.png"},{"name":"Demetrius","rarity":"rare","id":"demetrius","subtitle":"Villagers & NPCs","details":"Scientist husband of Robin and father of Maru, studying local plants and cave systems from his lab, and loving strawberries and ice cream.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f9/Demetrius.png"},{"name":"Evelyn","rarity":"rare","id":"evelyn","subtitle":"Villagers & NPCs","details":"Warm-hearted grandmother to Alex, living with George by the river, baking cookies for visitors, and loving beets, tulips, and chocolate cake.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8e/Evelyn.png"},{"name":"George","rarity":"rare","id":"george","subtitle":"Villagers & NPCs","details":"Wheelchair-using grandfather to Alex, gruff on the surface and tender underneath, who loves leeks and fried eel and watches TV at home with Evelyn.","image":"https://stardewvalleywiki.com/mediawiki/images/7/78/George.png"},{"name":"Gus","rarity":"rare","id":"gus","subtitle":"Villagers & NPCs","details":"Bartender-owner of the Stardrop Saloon, feeding the whole town nightly from behind the bar, and loving diamonds, oranges, and fish tacos.","image":"https://stardewvalleywiki.com/mediawiki/images/5/52/Gus.png"},{"name":"Jas","rarity":"rare","id":"jas","subtitle":"Villagers & NPCs","details":"Vincent's classmate and Pam's daughter, tutored by Penny at the museum, who loves fairy roses, pink cake, and playing in town with her friends.","image":"https://stardewvalleywiki.com/mediawiki/images/5/55/Jas.png"},{"name":"Jodi","rarity":"rare","id":"jodi","subtitle":"Villagers & NPCs","details":"Mother of Sam and Vincent and wife of Kent, keeping the house south of town running, and loving chocolate cake, pancakes, and vegetable medley.","image":"https://stardewvalleywiki.com/mediawiki/images/4/41/Jodi.png"},{"name":"Kent","rarity":"rare","id":"kent","subtitle":"Villagers & NPCs","details":"Soldier husband of Jodi and father of Sam and Vincent, who returns home from service in year two and loves roasted hazelnuts and fiddlehead risotto.","image":"https://stardewvalleywiki.com/mediawiki/images/9/99/Kent.png"},{"name":"Linus","rarity":"rare","id":"linus","subtitle":"Villagers & NPCs","details":"Gentle forager living in a tent north of town, at home in every season's wild places, who loves coconuts, cactus fruit, and dish o' the sea.","image":"https://stardewvalleywiki.com/mediawiki/images/3/31/Linus.png"},{"name":"Marnie","rarity":"rare","id":"marnie","subtitle":"Villagers & NPCs","details":"Ranch owner south of town who sells animals and supplies, aunt to Shane and great-aunt figure to Jas, and a lover of diamonds and farmer's lunch.","image":"https://stardewvalleywiki.com/mediawiki/images/5/52/Marnie.png"},{"name":"Pam","rarity":"rare","id":"pam","subtitle":"Villagers & NPCs","details":"Bus driver and mother of Penny, a saloon regular in the trailer east of town, who loves beer, pale ale, parsnips, and anything from a cactus.","image":"https://stardewvalleywiki.com/mediawiki/images/d/da/Pam.png"},{"name":"Pierre","rarity":"rare","id":"pierre","subtitle":"Villagers & NPCs","details":"General store owner and Abigail's father, proud of his shop and his back room stock, who loves fried calamari and guards his secret stash fiercely.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7e/Pierre.png"},{"name":"Robin","rarity":"rare","id":"robin","subtitle":"Villagers & NPCs","details":"Carpenter who builds farm buildings from her mountain shop, wife of Demetrius, mother of Maru and Sebastian, who loves peaches and goat cheese.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1b/Robin.png"},{"name":"Sandy","rarity":"rare","id":"sandy","subtitle":"Villagers & NPCs","details":"Desert shopkeeper at the Oasis and Emily's close friend, bright and welcoming to every bus arrival, who loves mango sticky rice and island flowers.","image":"https://stardewvalleywiki.com/mediawiki/images/4/4e/Sandy.png"},{"name":"Vincent","rarity":"rare","id":"vincent","subtitle":"Villagers & NPCs","details":"Jodi and Kent's youngest, Sam's little brother, an energetic kid tutored by Penny who loves grapes, cranberry candy, and anything sweet and fizzy.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Vincent.png"},{"name":"Willy","rarity":"rare","id":"willy","subtitle":"Villagers & NPCs","details":"Fisherman who runs the beach fish shop, tells tall tales of legendary catches, and loves catfish, sea cucumber, sturgeon, and a good mead.","image":"https://stardewvalleywiki.com/mediawiki/images/8/82/Willy.png"},{"name":"Gunther","rarity":"rare","id":"gunther","subtitle":"Villagers & NPCs","details":"Museum curator who catalogues every donated artifact and mineral, rewarding donors as the collection grows toward all ninety-five pieces.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3d/Gunther.png"},{"name":"Marlon","rarity":"uncommon","id":"marlon","subtitle":"Villagers & NPCs","details":"Adventurer's Guild leader beside the Mines, a one-eyed veteran who sells weapons and boots, checks slayer goals, and recovers lost items.","image":"https://stardewvalleywiki.com/mediawiki/images/3/37/Marlon.png"},{"name":"Birdie","rarity":"uncommon","id":"birdie","subtitle":"Villagers & NPCs","details":"Elderly islander on Ginger Island's north shore who trades island stories for help, loves tropical treats, and tends her late husband's parrot.","image":"https://stardewvalleywiki.com/mediawiki/images/4/46/Birdie.png"},{"name":"Professor Snail","rarity":"uncommon","id":"professor-snail","subtitle":"Villagers & NPCs","details":"Island field researcher in a volcano-side tent lab, cataloguing Ginger Island fossils and bones until his museum tent display stands complete.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d4/Professor_Snail.png"},{"name":"Morris","rarity":"uncommon","id":"morris","subtitle":"Villagers & NPCs","details":"JojaMart's local manager and the Community Center's corporate rival, offering a membership that turns bundles into warehouse renovations instead.","image":"https://stardewvalleywiki.com/mediawiki/images/9/90/Morris.png"},{"name":"Governor","rarity":"uncommon","id":"governor","subtitle":"Villagers & NPCs","details":"Dignitary in the fancy hat who tastes the Luau soup each summer and cuts the ribbon when the Community Center is finally restored to the town.","image":"https://stardewvalleywiki.com/mediawiki/images/4/46/Governor.png"},{"name":"Gil","rarity":"uncommon","id":"gil","subtitle":"Villagers & NPCs","details":"Quiet second-in-command at the Adventurer's Guild, dozing in his rocking chair between monster tallies, ready with a reward for every slayer goal.","image":"https://stardewvalleywiki.com/mediawiki/images/6/64/Gil.png"},{"name":"Fizz","rarity":"common","id":"fizz","subtitle":"Villagers & NPCs","details":"Cheerful Joja special-services man who writes to successful farmers with a very expensive offer and meets them in a Ginger Island cave.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a3/Fizz_00.png"},{"name":"Witch","rarity":"common","id":"witch","subtitle":"Villagers & NPCs","details":"Veiled figure who flies over farms at night, cursing or blessing crops, livestock, and slimes with her unpredictable magic.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6e/Witch_Icon.png"},{"name":"Henchman","rarity":"common","id":"henchman","subtitle":"Villagers & NPCs","details":"Silent servant guarding the Witch's Hut, who only steps aside once the farmer brings the void mayonnaise he craves from the swamp trail.","image":"https://stardewvalleywiki.com/mediawiki/images/2/21/Henchman_Portrait_1.png"},{"name":"Bouncer","rarity":"common","id":"bouncer","subtitle":"Villagers & NPCs","details":"Large, polite doorman outside Mr. Qi's Calico Desert casino, who admits only farmers carrying the club card from a long chain of odd errands.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f5/Bouncer.png"},{"name":"Legend","rarity":"chase","id":"legend","subtitle":"Fish","details":"The rarest catch of all: a spring-only, rain-only legend of the mountain lake, demanding top fishing skill and a cast toward the submerged log.","image":"https://stardewvalleywiki.com/mediawiki/images/1/10/Legend.png"},{"name":"Crimsonfish","rarity":"legendary","id":"crimsonfish","subtitle":"Fish","details":"Legendary summer catch found off the beach's east pier, available only once per farm and only to an angler with solid fishing experience.","image":"https://stardewvalleywiki.com/mediawiki/images/d/dc/Crimsonfish.png"},{"name":"Angler","rarity":"legendary","id":"angler","subtitle":"Fish","details":"Legendary fall catch hooked from the wooden bridge north of JojaMart, the gentlest of the legends but still a once-only trophy fish.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bf/Angler.png"},{"name":"Glacierfish","rarity":"legendary","id":"glacierfish","subtitle":"Fish","details":"Legendary winter catch lurking south of Arrowhead Island in Cindersap Forest, a slippery trophy that tests even well-geared winter anglers.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fd/Glacierfish.png"},{"name":"Mutant Carp","rarity":"legendary","id":"mutant-carp","subtitle":"Fish","details":"Legendary catch swimming the sewers in any season and any weather, its strange colour blamed on whatever Pelican Town washes away.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cb/Mutant_Carp.png"},{"name":"Legend II","rarity":"legendary","id":"legend-ii","subtitle":"Fish","details":"Extended-family cousin of the Legend, appearing in the mountain lake only during Mr. Qi's special quest, at the same rainy spring log.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7a/Legend_II.png"},{"name":"Lava Eel","rarity":"legendary","id":"lava-eel","subtitle":"Fish","details":"One of the trickiest ordinary fish: hooked in the lava lake deep in the Mines and at the volcano caldera, in any season, at punishing odds.","image":"https://stardewvalleywiki.com/mediawiki/images/1/12/Lava_Eel.png"},{"name":"Glacierfish Jr.","rarity":"epic","id":"glacierfish-jr","subtitle":"Fish","details":"Extended-family youngster of the Glacierfish, found south of Arrowhead Island only while Mr. Qi's Extended Family quest is running.","image":"https://stardewvalleywiki.com/mediawiki/images/d/db/Glacierfish_Jr..png"},{"name":"Ms. Angler","rarity":"epic","id":"ms-angler","subtitle":"Fish","details":"Extended-family counterpart of the Angler, hooked north of JojaMart only during Mr. Qi's quest and named with unusual formality.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bb/Ms._Angler.png"},{"name":"Son of Crimsonfish","rarity":"epic","id":"son-of-crimsonfish","subtitle":"Fish","details":"Extended-family heir to the Crimsonfish, waiting off the beach's east pier only while the Extended Family quest is active.","image":"https://stardewvalleywiki.com/mediawiki/images/1/12/Son_of_Crimsonfish.png"},{"name":"Radioactive Carp","rarity":"epic","id":"radioactive-carp","subtitle":"Fish","details":"Glowing extended-family carp of the sewers, catchable only during Mr. Qi's Extended Family quest and best kept well away from dinner.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/Radioactive_Carp.png"},{"name":"Super Cucumber","rarity":"epic","id":"super-cucumber","subtitle":"Fish","details":"Silky, cucumber-shaped ocean fish of summer and fall nights, prized for ponds, sushi, and the fishing quests that ask for something rarer.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d5/Super_Cucumber.png"},{"name":"Ice Pip","rarity":"epic","id":"ice-pip","subtitle":"Fish","details":"Tiny, valuable fish of the icy Mines lake on the frozen floors, found year-round where the water stays cold beneath the stone.","image":"https://stardewvalleywiki.com/mediawiki/images/6/63/Ice_Pip.png"},{"name":"Scorpion Carp","rarity":"epic","id":"scorpion-carp","subtitle":"Fish","details":"Prickly desert pond fish caught by day in the Calico Desert, so dangerous out of water that its sting is part of its reputation.","image":"https://stardewvalleywiki.com/mediawiki/images/7/76/Scorpion_Carp.png"},{"name":"Void Salmon","rarity":"epic","id":"void-salmon","subtitle":"Fish","details":"Purple fish of the Witch's Swamp, reached only late and in secret, swimming water no ordinary valley fish would survive in.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ad/Void_Salmon.png"},{"name":"Stingray","rarity":"epic","id":"stingray","subtitle":"Fish","details":"Striped island fish of Pirate Cove on Ginger Island, catchable day or night in the cove's hidden freshwater pool among the palms.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3a/Stingray.png"},{"name":"Octopus","rarity":"rare","id":"octopus","subtitle":"Fish","details":"Summer ocean fish of the morning hours, also riding the Night Market submarine, with eight arms and a very high price for its trouble.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5a/Octopus.png"},{"name":"Pufferfish","rarity":"rare","id":"pufferfish","subtitle":"Fish","details":"Round summer ocean fish that appears on sunny afternoons, beloved as a gift, dangerous to eat raw, and wanted for more than one quest.","image":"https://stardewvalleywiki.com/mediawiki/images/b/ba/Pufferfish.png"},{"name":"Catfish","rarity":"rare","id":"catfish","subtitle":"Fish","details":"Rain-loving river fish of spring and fall, also found in forest water, famous for leaping into catfish ponds and demanding dinners alike.","image":"https://stardewvalleywiki.com/mediawiki/images/9/99/Catfish.png"},{"name":"Sturgeon","rarity":"rare","id":"sturgeon","subtitle":"Fish","details":"Mountain lake fish of summer and winter days, raised in ponds for caviar and respected as one of the harder everyday catches to land.","image":"https://stardewvalleywiki.com/mediawiki/images/4/42/Sturgeon.png"},{"name":"Tiger Trout","rarity":"rare","id":"tiger-trout","subtitle":"Fish","details":"Tiger-striped river fish of fall and winter that never runs in the mountain lake, keeping strictly to town and forest moving water.","image":"https://stardewvalleywiki.com/mediawiki/images/0/01/Tiger_Trout.png"},{"name":"Midnight Carp","rarity":"rare","id":"midnight-carp","subtitle":"Fish","details":"Late-night fish of mountain and forest lakes in fall and winter, surfacing after ten and vanishing again in the small hours.","image":"https://stardewvalleywiki.com/mediawiki/images/3/33/Midnight_Carp.png"},{"name":"Lionfish","rarity":"rare","id":"lionfish","subtitle":"Fish","details":"Bright Ginger Island ocean fish found in daylight, tropical, social in ponds, and quicker than its relaxed island home would suggest.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bb/Lionfish.png"},{"name":"Blue Discus","rarity":"rare","id":"blue-discus","subtitle":"Fish","details":"Tropical freshwater fish of Ginger Island's rivers and ponds, a calm blue catch for sunny island days away from the volcano.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ee/Blue_Discus.png"},{"name":"Spook Fish","rarity":"rare","id":"spook-fish","subtitle":"Fish","details":"Deep-sea oddity from the Night Market submarine in mid-winter, travelling with midnight squid and blobfish far below the beach.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8c/Spook_Fish.png"},{"name":"Blobfish","rarity":"rare","id":"blobfish","subtitle":"Fish","details":"Blob-shaped deep-sea fish from the Night Market submarine, slow, strange, and valuable enough to justify three winter nights of diving.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7f/Blobfish.png"},{"name":"Salmon","rarity":"uncommon","id":"salmon","subtitle":"Fish","details":"Fall river fish running upstream through town in daylight, a classic seasonal catch that ends its run as salmon dinner for someone.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e0/Salmon.png"},{"name":"Tuna","rarity":"uncommon","id":"tuna","subtitle":"Fish","details":"Ocean fish of summer and winter, a broad, flat staple of the beach catch and a dependable earner for early fishing at Willy's pier.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c5/Tuna.png"},{"name":"Eel","rarity":"uncommon","id":"eel","subtitle":"Fish","details":"Ocean eel of rainy spring and fall nights, slipping out after dark and into spicy eel, fried eel, and more than one loved dinner.","image":"https://stardewvalleywiki.com/mediawiki/images/9/91/Eel.png"},{"name":"Squid","rarity":"uncommon","id":"squid","subtitle":"Fish","details":"Winter evening ocean fish, also met in deep and dangerous water, whose ink becomes a cooking ingredient in its own right.","image":"https://stardewvalleywiki.com/mediawiki/images/8/81/Squid.png"},{"name":"Halibut","rarity":"uncommon","id":"halibut","subtitle":"Fish","details":"Ocean fish across spring, summer, and winter, at home near the beach in most hours and a solid mid-tier catch for new rods.","image":"https://stardewvalleywiki.com/mediawiki/images/0/02/Halibut.png"},{"name":"Lingcod","rarity":"uncommon","id":"lingcod","subtitle":"Fish","details":"Winter river and lake fish with a fierce reputation, lingering near town and mountain water through the coldest part of the year.","image":"https://stardewvalleywiki.com/mediawiki/images/8/87/Lingcod.png"},{"name":"Rainbow Trout","rarity":"uncommon","id":"rainbow-trout","subtitle":"Fish","details":"Summer sun-loving trout of rivers and the mountain lake, most active on bright days and happiest in a bowl of trout soup.","image":"https://stardewvalleywiki.com/mediawiki/images/1/14/Rainbow_Trout.png"},{"name":"Dorado","rarity":"uncommon","id":"dorado","subtitle":"Fish","details":"Summer forest river fish, golden and quick in daylight, found where the Cindersap river runs clear below the farm's southern woods.","image":"https://stardewvalleywiki.com/mediawiki/images/1/18/Dorado.png"},{"name":"Flounder","rarity":"uncommon","id":"flounder","subtitle":"Fish","details":"Flat ocean fish of spring and summer, also found around Ginger Island, flopping sideways into fish ponds and simple suppers.","image":"https://stardewvalleywiki.com/mediawiki/images/8/85/Flounder.png"},{"name":"Midnight Squid","rarity":"uncommon","id":"midnight-squid","subtitle":"Fish","details":"Submarine-only squid of the Night Market, inking the deep water in mid-winter alongside spook fish and blobfish for three nights only.","image":"https://stardewvalleywiki.com/mediawiki/images/8/83/Midnight_Squid.png"},{"name":"Ghostfish","rarity":"uncommon","id":"ghostfish","subtitle":"Fish","details":"Pale fish of the Mines' underground lakes, said to feed on ectoplasm left by its ghostly neighbours and to drop it when caught.","image":"https://stardewvalleywiki.com/mediawiki/images/7/72/Ghostfish.png"},{"name":"Stonefish","rarity":"uncommon","id":"stonefish","subtitle":"Fish","details":"Camouflaged Mines fish that looks exactly like the floor it hides on, hooked from the shallow underground lake near the entrance floors.","image":"https://stardewvalleywiki.com/mediawiki/images/0/03/Stonefish.png"},{"name":"Sandfish","rarity":"uncommon","id":"sandfish","subtitle":"Fish","details":"Desert pond fish of daylight hours, sold dear, used in quality cooking, and loved as a gift by at least one desert-minded reader.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bb/Sandfish.png"},{"name":"Slimejack","rarity":"uncommon","id":"slimejack","subtitle":"Fish","details":"Green-tinted fish of the Mutant Bug Lair, thriving in slime-rich water behind the sewers where almost nothing else dares to swim.","image":"https://stardewvalleywiki.com/mediawiki/images/3/34/Slimejack.png"},{"name":"Goby","rarity":"uncommon","id":"goby","subtitle":"Fish","details":"Waterfall fish added to the forest's southern falls, plunging and leaping where Cindersap water drops toward the wizard's woods.","image":"https://stardewvalleywiki.com/mediawiki/images/6/67/Goby.png"},{"name":"Albacore","rarity":"uncommon","id":"albacore","subtitle":"Fish","details":"Ocean fish of fall and winter mornings and evenings, a tuna relative that rewards anglers who time the pier rather than camp it.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e1/Albacore.png"},{"name":"Sea Cucumber","rarity":"uncommon","id":"sea-cucumber","subtitle":"Fish","details":"Cucumber-shaped ocean fish of fall and winter, disliked by most as a gift, demanded by fish ponds, and nothing like the super kind.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a9/Sea_Cucumber.png"},{"name":"Red Snapper","rarity":"uncommon","id":"red-snapper","subtitle":"Fish","details":"Rainy-day ocean snapper of summer and fall, also visiting Ginger Island water, turning up red and lively after wet weather.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d3/Red_Snapper.png"},{"name":"Pike","rarity":"uncommon","id":"pike","subtitle":"Fish","details":"River and forest pond fish of summer and winter, a northern staple found in most moving freshwater away from the mountains.","image":"https://stardewvalleywiki.com/mediawiki/images/3/31/Pike.png"},{"name":"Walleye","rarity":"uncommon","id":"walleye","subtitle":"Fish","details":"Nocturnal fall fish of rivers and lakes, biting on rainy nights until two in the morning and starring in midnight suppers.","image":"https://stardewvalleywiki.com/mediawiki/images/0/05/Walleye.png"},{"name":"Anchovy","rarity":"common","id":"anchovy","subtitle":"Fish","details":"Tiny ocean fish of spring and fall, the classic first catch off the pier and the humble backbone of sardine-based cooking.","image":"https://stardewvalleywiki.com/mediawiki/images/7/79/Anchovy.png"},{"name":"Bream","rarity":"common","id":"bream","subtitle":"Fish","details":"Nocturnal river fish found year-round after six in the evening, quiet, common, and perfect for learning the river at night.","image":"https://stardewvalleywiki.com/mediawiki/images/8/82/Bream.png"},{"name":"Largemouth Bass","rarity":"common","id":"largemouth-bass","subtitle":"Fish","details":"Mountain lake bass found in any season, a favourite early trophy that grows bold in a pond and sells steadily all year.","image":"https://stardewvalleywiki.com/mediawiki/images/1/11/Largemouth_Bass.png"},{"name":"Smallmouth Bass","rarity":"common","id":"smallmouth-bass","subtitle":"Fish","details":"Town river and forest pond bass of spring and fall, smaller than its mountain cousin and happiest in slow, weedy water.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a5/Smallmouth_Bass.png"},{"name":"Perch","rarity":"common","id":"perch","subtitle":"Fish","details":"Winter freshwater fish of rivers, lakes, and forest ponds, a cold-season regular that keeps winter fishing worthwhile.","image":"https://stardewvalleywiki.com/mediawiki/images/4/43/Perch.png"},{"name":"Carp","rarity":"common","id":"carp","subtitle":"Fish","details":"Patient lake fish found almost anywhere still — lakes, the Secret Woods, even the sewers — in spring, summer, and fall.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a8/Carp.png"},{"name":"Sunfish","rarity":"common","id":"sunfish","subtitle":"Fish","details":"Sunny-day river fish of spring and summer, small, bright, and one of the friendliest first casts a new farmer can make.","image":"https://stardewvalleywiki.com/mediawiki/images/5/56/Sunfish.png"},{"name":"Red Mullet","rarity":"common","id":"red-mullet","subtitle":"Fish","details":"Ocean fish of summer and winter off the beach pier, a red, spiny regular in the warm-season catch and in fish pond requests.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f2/Red_Mullet.png"},{"name":"Herring","rarity":"common","id":"herring","subtitle":"Fish","details":"Ocean fish of spring and winter, small and silvery in shoals, filling crab pots, creels, and winter market stalls alike.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Herring.png"},{"name":"Tilapia","rarity":"common","id":"tilapia","subtitle":"Fish","details":"Warm-water fish of summer and fall found in both ocean and Ginger Island freshwater, placid in ponds and steady on the line.","image":"https://stardewvalleywiki.com/mediawiki/images/7/73/Tilapia.png"},{"name":"Chub","rarity":"common","id":"chub","subtitle":"Fish","details":"Forest lake and river fish found in any season and almost any weather, a whiskered regular of Cindersap's quieter water.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bd/Chub.png"},{"name":"Shad","rarity":"common","id":"shad","subtitle":"Fish","details":"River fish of spring, summer, and fall that runs only on rainy daylight hours, arriving with the wet weather like clockwork.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ef/Shad.png"},{"name":"Bullhead","rarity":"common","id":"bullhead","subtitle":"Fish","details":"Mountain lake fish found in any season, round-headed and unhurried, a reliable catch beside the carpenter's shop and the mines.","image":"https://stardewvalleywiki.com/mediawiki/images/d/db/Bullhead.png"},{"name":"Sardine","rarity":"common","id":"sardine","subtitle":"Fish","details":"Daytime ocean fish of spring, fall, and winter, tiny in the hand and mighty in recipes from sashimi to dish o' the sea.","image":"https://stardewvalleywiki.com/mediawiki/images/0/04/Sardine.png"},{"name":"Woodskip","rarity":"common","id":"woodskip","subtitle":"Fish","details":"Secret Woods pond fish found in any season, skipping across dark water where the fallen logs hide the woods' oldest trees.","image":"https://stardewvalleywiki.com/mediawiki/images/9/97/Woodskip.png"},{"name":"Sea Jelly","rarity":"common","id":"sea-jelly","subtitle":"Fish","details":"Jelly caught while ocean fishing in spring, summer, or fall, granting a fishing boost and a wobble in place of a fight.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d5/Sea_Jelly.png"},{"name":"Crab","rarity":"common","id":"crab","subtitle":"Fish","details":"Ocean crab-pot catch found year-round, also scuttling out of rock crabs, and essential for crab cakes and lucky lunches alike.","image":"https://stardewvalleywiki.com/mediawiki/images/6/63/Crab.png"},{"name":"Lobster","rarity":"common","id":"lobster","subtitle":"Fish","details":"Ocean crab-pot catch in a heavy shell, the key to lobster bisque and one of the priciest things a pot can pull up.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9f/Lobster.png"},{"name":"Crayfish","rarity":"common","id":"crayfish","subtitle":"Fish","details":"Freshwater crab-pot catch from lakes and rivers, humble, muddy, and quietly useful in cooking and in Willy's early quests.","image":"https://stardewvalleywiki.com/mediawiki/images/5/53/Crayfish.png"},{"name":"Shrimp","rarity":"common","id":"shrimp","subtitle":"Fish","details":"Ocean crab-pot shrimp found year-round, small in size and large in usefulness, from shrimp cocktail to salads and quests.","image":"https://stardewvalleywiki.com/mediawiki/images/9/91/Shrimp.png"},{"name":"Snail","rarity":"common","id":"snail","subtitle":"Fish","details":"Freshwater crab-pot snail, slow even by snail standards, loved by almost nobody as a gift and at home in any farm pond.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d2/Snail.png"},{"name":"Periwinkle","rarity":"common","id":"periwinkle","subtitle":"Fish","details":"Freshwater crab-pot catch with a spiral shell, an unlikely cooking ingredient that somehow ends up inside a strange bun.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1d/Periwinkle.png"},{"name":"Oyster","rarity":"common","id":"oyster","subtitle":"Fish","details":"Ocean crab-pot and beach-foraged shellfish, plain on its own and prized ground down or cooked into rich valley dishes.","image":"https://stardewvalleywiki.com/mediawiki/images/5/54/Oyster.png"},{"name":"Clam","rarity":"common","id":"clam","subtitle":"Fish","details":"Beach-foraged shell found in every season along the tide line, also fished from the ocean and used in makers and decorations.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ed/Clam.png"},{"name":"Cockle","rarity":"common","id":"cockle","subtitle":"Fish","details":"Beach shellfish foraged in any season and caught in ocean crab pots, a small, ridged staple of the shoreline economy.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ad/Cockle.png"},{"name":"Mussel","rarity":"common","id":"mussel","subtitle":"Fish","details":"Beach shellfish clinging to the tide pools in any season, foraged by hand and caught in crab pots along the ocean shore.","image":"https://stardewvalleywiki.com/mediawiki/images/a/aa/Mussel.png"},{"name":"Ancient Fruit","rarity":"legendary","id":"ancient-fruit","subtitle":"Crops, Fruit & Forage","details":"Ancient crop grown spring through fall from a museum-restored seed, taking a month to mature then regrowing weekly fruit made for the keg.","image":"https://stardewvalleywiki.com/mediawiki/images/0/01/Ancient_Fruit.png"},{"name":"Sweet Gem Berry","rarity":"legendary","id":"sweet-gem-berry","subtitle":"Crops, Fruit & Forage","details":"Immensely sweet berry grown in fall from a rare seed, never made into wine or jelly, and traded whole to a statue for something shining.","image":"https://stardewvalleywiki.com/mediawiki/images/8/88/Sweet_Gem_Berry.png"},{"name":"Starfruit","rarity":"epic","id":"starfruit","subtitle":"Crops, Fruit & Forage","details":"Summer crop from desert seed that matures in under two weeks and becomes some of the most valuable wine and jelly on any farm.","image":"https://stardewvalleywiki.com/mediawiki/images/d/db/Starfruit.png"},{"name":"Fairy Rose","rarity":"epic","id":"fairy-rose","subtitle":"Crops, Fruit & Forage","details":"Fall flower whose nearby beehives make the priciest honey, loved by Jas, Vincent, and Evelyn, and sown thick around the fairy folklore.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5c/Fairy_Rose.png"},{"name":"Pineapple","rarity":"epic","id":"pineapple","subtitle":"Crops, Fruit & Forage","details":"Tropical summer fruit, at home on Ginger Island and in the greenhouse, regrowing after harvest and brightening curries and puddings.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fb/Pineapple.png"},{"name":"Cactus Fruit","rarity":"epic","id":"cactus-fruit","subtitle":"Crops, Fruit & Forage","details":"Desert forage fruit and greenhouse crop, spiky outside and sweet inside, loved by Sam and Pam and gathered where the bus stops.","image":"https://stardewvalleywiki.com/mediawiki/images/3/32/Cactus_Fruit.png"},{"name":"Mango","rarity":"epic","id":"mango","subtitle":"Crops, Fruit & Forage","details":"Tropical tree fruit ripening in summer on Ginger Island, loved by Leo and Gus, and turned into sticky rice, curry, and island drinks.","image":"https://stardewvalleywiki.com/mediawiki/images/3/38/Mango.png"},{"name":"Strawberry","rarity":"rare","id":"strawberry","subtitle":"Crops, Fruit & Forage","details":"Spring berries bought first at the Egg Festival, regrowing every few days once ripe and fuelling jam, wine, and Maru's loved gifts.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6d/Strawberry.png"},{"name":"Melon","rarity":"rare","id":"melon","subtitle":"Crops, Fruit & Forage","details":"Summer crop that can grow into a giant melon with its neighbours, loved by Penny, and made into fruit salad and pink cake.","image":"https://stardewvalleywiki.com/mediawiki/images/1/19/Melon.png"},{"name":"Pumpkin","rarity":"rare","id":"pumpkin","subtitle":"Crops, Fruit & Forage","details":"Fall crop that can grow giant in a three-by-three patch, loved across town, and carved into pies, soups, and festival displays.","image":"https://stardewvalleywiki.com/mediawiki/images/6/64/Pumpkin.png"},{"name":"Cranberries","rarity":"rare","id":"cranberries","subtitle":"Crops, Fruit & Forage","details":"Fall trellis-free berry crop that yields several berries per plant again and again, pouring into jelly, wine, and sauce all season.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6e/Cranberries.png"},{"name":"Coffee Bean","rarity":"rare","id":"coffee-bean","subtitle":"Crops, Fruit & Forage","details":"Spring and summer bean that is both seed and harvest, regrowing steadily and brewed five at a time into fast, beloved coffee.","image":"https://stardewvalleywiki.com/mediawiki/images/3/33/Coffee_Bean.png"},{"name":"Banana","rarity":"rare","id":"banana","subtitle":"Crops, Fruit & Forage","details":"Tropical tree fruit of summer Ginger Island and the greenhouse, loved in puddings and drinks and ripening on its own island tree.","image":"https://stardewvalleywiki.com/mediawiki/images/6/69/Banana.png"},{"name":"Cauliflower","rarity":"uncommon","id":"cauliflower","subtitle":"Crops, Fruit & Forage","details":"Spring crop that can merge into a giant cauliflower, a heavy early earner that anchors spring cooking and cheese cauliflower.","image":"https://stardewvalleywiki.com/mediawiki/images/a/aa/Cauliflower.png"},{"name":"Rhubarb","rarity":"uncommon","id":"rhubarb","subtitle":"Crops, Fruit & Forage","details":"Spring crop from desert seed, tart and red, baked into pies loved by Maru and Demetrius and priced for patient spring farmers.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6e/Rhubarb.png"},{"name":"Blueberry","rarity":"uncommon","id":"blueberry","subtitle":"Crops, Fruit & Forage","details":"Summer crop yielding several berries per harvest and regrowing for weeks, the backbone of preserves, wine, and summer income.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9e/Blueberry.png"},{"name":"Hot Pepper","rarity":"uncommon","id":"hot-pepper","subtitle":"Crops, Fruit & Forage","details":"Summer crop that regrows peppers all season, firing up pepper poppers, spicy eel, and Shane's very favourite snacks.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Hot_Pepper.png"},{"name":"Tomato","rarity":"uncommon","id":"tomato","subtitle":"Crops, Fruit & Forage","details":"Summer crop that keeps producing ripe tomatoes for salads, medleys, pizzas, and sauces long after its first harvest.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9d/Tomato.png"},{"name":"Corn","rarity":"uncommon","id":"corn","subtitle":"Crops, Fruit & Forage","details":"Tall crop spanning summer and fall, regrowing ears for cooking, tortillas, and animal feed while standing through two seasons.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f8/Corn.png"},{"name":"Wheat","rarity":"uncommon","id":"wheat","subtitle":"Crops, Fruit & Forage","details":"Summer and fall grain cut with a scythe, milled into flour, brewed into beer, and stored as hay when grown from grass starter kin.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e2/Wheat.png"},{"name":"Hops","rarity":"uncommon","id":"hops","subtitle":"Crops, Fruit & Forage","details":"Summer trellis crop that regrows daily once mature, filling kegs with pale ale and trellis rows no farmer can walk through.","image":"https://stardewvalleywiki.com/mediawiki/images/5/59/Hops.png"},{"name":"Grape","rarity":"uncommon","id":"grape","subtitle":"Crops, Fruit & Forage","details":"Fall trellis crop that regrows grapes, also foraged wild in summer, and becomes jelly, wine, and Vincent's favourite snacks.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c2/Grape.png"},{"name":"Eggplant","rarity":"uncommon","id":"eggplant","subtitle":"Crops, Fruit & Forage","details":"Fall crop that regrows glossy eggplants for parmesan and stir fries, returning again and again until the first frost.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8f/Eggplant.png"},{"name":"Yam","rarity":"uncommon","id":"yam","subtitle":"Crops, Fruit & Forage","details":"Fall root crop dug for roasts and glazed yams, a quiet earner that Pam loves glazed and monsters ignore completely.","image":"https://stardewvalleywiki.com/mediawiki/images/5/52/Yam.png"},{"name":"Artichoke","rarity":"uncommon","id":"artichoke","subtitle":"Crops, Fruit & Forage","details":"Fall crop prized by chefs and gift-givers, available beyond the first year and baked into dips and hearty autumn dishes.","image":"https://stardewvalleywiki.com/mediawiki/images/d/dd/Artichoke.png"},{"name":"Beet","rarity":"uncommon","id":"beet","subtitle":"Crops, Fruit & Forage","details":"Fall root crop from Oasis seed, milled into sugar, cooked into beet salads, and dyed into rich colours at the sewing machine.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a4/Beet.png"},{"name":"Sunflower","rarity":"uncommon","id":"sunflower","subtitle":"Crops, Fruit & Forage","details":"Summer and fall flower grown for seeds, oil, and bouquets, loved by Haley and disliked only by villagers with no romance.","image":"https://stardewvalleywiki.com/mediawiki/images/8/81/Sunflower.png"},{"name":"Poppy","rarity":"uncommon","id":"poppy","subtitle":"Crops, Fruit & Forage","details":"Summer flower that Penny loves and most others hate, grown for poppyseed muffins and remembered fields of bright red blooms.","image":"https://stardewvalleywiki.com/mediawiki/images/3/37/Poppy.png"},{"name":"Red Cabbage","rarity":"uncommon","id":"red-cabbage","subtitle":"Crops, Fruit & Forage","details":"Summer crop that arrives in later seed catalogues, baked into red plates and slaws and loved for its vivid crimson leaves.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2d/Red_Cabbage.png"},{"name":"Taro Root","rarity":"uncommon","id":"taro-root","subtitle":"Crops, Fruit & Forage","details":"Island root crop that thrives near water in summer, dug from Ginger Island soil and cooked by Leo's people into soft poi.","image":"https://stardewvalleywiki.com/mediawiki/images/0/01/Taro_Root.png"},{"name":"Parsnip","rarity":"common","id":"parsnip","subtitle":"Crops, Fruit & Forage","details":"Spring's first and fastest crop, ready in days, eaten in soups and lunches, and forever tied to the farm's very first harvest.","image":"https://stardewvalleywiki.com/mediawiki/images/d/db/Parsnip.png"},{"name":"Green Bean","rarity":"common","id":"green-bean","subtitle":"Crops, Fruit & Forage","details":"Spring trellis bean that regrows pods for hotpots and lunches, climbing neat rows that block the farmer as surely as hops.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5c/Green_Bean.png"},{"name":"Potato","rarity":"common","id":"potato","subtitle":"Crops, Fruit & Forage","details":"Spring crop that sometimes yields a bonus tuber per plant, fuelling hashbrowns, soups, and the valley's appetite for fried food.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c2/Potato.png"},{"name":"Garlic","rarity":"common","id":"garlic","subtitle":"Crops, Fruit & Forage","details":"Spring crop of the second year onward, pungent in the field and invaluable in cooking, warding off nothing but bland meals.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cc/Garlic.png"},{"name":"Kale","rarity":"common","id":"kale","subtitle":"Crops, Fruit & Forage","details":"Spring scythe-harvested greens that go into salads and stir fries, sturdy, early, and disliked by almost no one in town.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d1/Kale.png"},{"name":"Blue Jazz","rarity":"common","id":"blue-jazz","subtitle":"Crops, Fruit & Forage","details":"Spring flower with a soft blue bloom, making gentle honey and a prettier spring field than any plain vegetable patch.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2f/Blue_Jazz.png"},{"name":"Tulip","rarity":"common","id":"tulip","subtitle":"Crops, Fruit & Forage","details":"Spring flower in warm colours, grown for bouquets and honey, given often to neighbours and pressed into spring displays.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cf/Tulip.png"},{"name":"Radish","rarity":"common","id":"radish","subtitle":"Crops, Fruit & Forage","details":"Summer root crop, crisp and peppery in salads, loved in red plates and grown quickly between longer summer plantings.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d5/Radish.png"},{"name":"Summer Spangle","rarity":"common","id":"summer-spangle","subtitle":"Crops, Fruit & Forage","details":"Summer flower in spangled colours that Caroline loves, brightening fields, bouquets, honey jars, and midsummer gift baskets.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9f/Summer_Spangle.png"},{"name":"Bok Choy","rarity":"common","id":"bok-choy","subtitle":"Crops, Fruit & Forage","details":"Fall leafy crop for stir fries and medleys, quick to mature and as dependable as the season's first cool evenings.","image":"https://stardewvalleywiki.com/mediawiki/images/4/40/Bok_Choy.png"},{"name":"Amaranth","rarity":"common","id":"amaranth","subtitle":"Crops, Fruit & Forage","details":"Fall grain with deep purple seeds, grown for Marnie's ranch request and milled, cooked, and gifted through the harvest season.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f6/Amaranth.png"},{"name":"Unmilled Rice","rarity":"common","id":"unmilled-rice","subtitle":"Crops, Fruit & Forage","details":"Spring rice grown best in water near ponds and rivers, milled from shoots into the grain behind puddings and maki rolls.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fe/Unmilled_Rice.png"},{"name":"Ginger","rarity":"common","id":"ginger","subtitle":"Crops, Fruit & Forage","details":"Island root dug and foraged across Ginger Island, brewed into lucky ginger ale and cooked into curries, soups, and island dishes.","image":"https://stardewvalleywiki.com/mediawiki/images/8/85/Ginger.png"},{"name":"Carrot","rarity":"common","id":"carrot","subtitle":"Crops, Fruit & Forage","details":"Quick spring root crop, crunchy and bright, pulled early in the season and snacked, juiced, and cooked across the farm.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c3/Carrot.png"},{"name":"Summer Squash","rarity":"common","id":"summer-squash","subtitle":"Crops, Fruit & Forage","details":"Regrowing summer squash found through island and raccoon channels, a warm-season staple for grills and vegetable medleys.","image":"https://stardewvalleywiki.com/mediawiki/images/4/43/Summer_Squash.png"},{"name":"Broccoli","rarity":"common","id":"broccoli","subtitle":"Crops, Fruit & Forage","details":"Fall crop that regrows cool-season florets, green and hearty, introduced for farmers who thought fall ended with pumpkins.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Broccoli.png"},{"name":"Powdermelon","rarity":"common","id":"powdermelon","subtitle":"Crops, Fruit & Forage","details":"Winter melon that can grow giant in the cold, dusted like powder, and stands alone as a true crop of the quiet season.","image":"https://stardewvalleywiki.com/mediawiki/images/a/aa/Powdermelon.png"},{"name":"Apple","rarity":"common","id":"apple","subtitle":"Crops, Fruit & Forage","details":"Fall fruit tree harvest, ripening daily in season from a sapling planted a month ahead, baked into pies and cider alike.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7d/Apple.png"},{"name":"Apricot","rarity":"common","id":"apricot","subtitle":"Crops, Fruit & Forage","details":"Spring fruit tree harvest, the year's first orchard fruit, small and sweet in preserves, salads, and early gift baskets.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fc/Apricot.png"},{"name":"Cherry","rarity":"common","id":"cherry","subtitle":"Crops, Fruit & Forage","details":"Spring fruit tree harvest that arrives daily in season, dark, sweet, and ready for jams, cakes, and brandy experiments.","image":"https://stardewvalleywiki.com/mediawiki/images/2/20/Cherry.png"},{"name":"Orange","rarity":"common","id":"orange","subtitle":"Crops, Fruit & Forage","details":"Summer fruit tree harvest gathered daily in season, bright and juicy for Gus's loved gifts, juices, and summer preserves.","image":"https://stardewvalleywiki.com/mediawiki/images/4/43/Orange.png"},{"name":"Peach","rarity":"common","id":"peach","subtitle":"Crops, Fruit & Forage","details":"Summer fruit tree harvest, soft and fragrant at ripeness, loved by Robin and Elliott and baked into cobblers and cakes.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e2/Peach.png"},{"name":"Pomegranate","rarity":"common","id":"pomegranate","subtitle":"Crops, Fruit & Forage","details":"Fall fruit tree harvest with seeds like jewels, loved by Elliott and Linus and glowing in salads and winter-star gifts.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1b/Pomegranate.png"},{"name":"Salmonberry","rarity":"common","id":"salmonberry","subtitle":"Crops, Fruit & Forage","details":"Spring forage berries bursting from bushes for a few mid-spring days, eaten by hand and baked into cobblers by the basketful.","image":"https://stardewvalleywiki.com/mediawiki/images/5/59/Salmonberry.png"},{"name":"Blackberry","rarity":"common","id":"blackberry","subtitle":"Crops, Fruit & Forage","details":"Fall forage berries darkening bushes in mid-fall, gathered by the dozen into cobblers, jellies, and Linus's wild snacks.","image":"https://stardewvalleywiki.com/mediawiki/images/2/25/Blackberry.png"},{"name":"Wild Plum","rarity":"common","id":"wild-plum","subtitle":"Crops, Fruit & Forage","details":"Fall forage fruit found under forest and mountain trees, tart and purple, made into jelly and plum pudding through autumn.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3b/Wild_Plum.png"},{"name":"Coconut","rarity":"common","id":"coconut","subtitle":"Crops, Fruit & Forage","details":"Foraged year-round in the desert and on Ginger Island, cracked for coconut milk, tropical curry, and Sandy's desert welcome.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2f/Coconut.png"},{"name":"Fiddlehead Fern","rarity":"common","id":"fiddlehead-fern","subtitle":"Crops, Fruit & Forage","details":"Summer forage fern of the Secret Woods and island jungle, steamed into risotto loved by Clint and Kent and gathered in shade.","image":"https://stardewvalleywiki.com/mediawiki/images/4/48/Fiddlehead_Fern.png"},{"name":"Morel","rarity":"common","id":"morel","subtitle":"Crops, Fruit & Forage","details":"Spring forage mushroom of the Secret Woods and forest farms, earthy and prized in cooking, appearing where the light stays dim.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b1/Morel.png"},{"name":"Leek","rarity":"common","id":"leek","subtitle":"Crops, Fruit & Forage","details":"Spring forage vegetable found across the valley's grass, loved by George, made into salads, and marking the season's first walks.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/Leek.png"},{"name":"Lucky Lunch","rarity":"legendary","id":"lucky-lunch","subtitle":"Cooking & Food","details":"Lucky dish of sea cucumber, tortilla, and shrimp that grants strong luck, learned from the Queen of Sauce for fortunate days.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5d/Lucky_Lunch.png"},{"name":"Seafoam Pudding","rarity":"legendary","id":"seafoam-pudding","subtitle":"Cooking & Food","details":"Flounder, midnight carp, and squid ink pudding granting the strongest fishing boost, learned late from the Queen of Sauce.","image":"https://stardewvalleywiki.com/mediawiki/images/3/33/Seafoam_Pudding.png"},{"name":"Triple Shot Espresso","rarity":"epic","id":"triple-shot-espresso","subtitle":"Cooking & Food","details":"Triple-strength coffee brewed from three cups at once, granting speed that lasts far longer than a single morning mug.","image":"https://stardewvalleywiki.com/mediawiki/images/3/36/Triple_Shot_Espresso.png"},{"name":"Strange Bun","rarity":"epic","id":"strange-bun","subtitle":"Cooking & Food","details":"Odd bun of wheat flour, periwinkle, and void mayonnaise, given by Shane, liked by Krobus, and occasionally dropped by shadow brutes.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5e/Strange_Bun.png"},{"name":"Pumpkin Pie","rarity":"epic","id":"pumpkin-pie","subtitle":"Cooking & Food","details":"Pumpkin, wheat flour, milk, and sugar pie from the Queen of Sauce, baked for fall tables and loved by villagers across town.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7d/Pumpkin_Pie.png"},{"name":"Tropical Curry","rarity":"epic","id":"tropical-curry","subtitle":"Cooking & Food","details":"Pineapple and coconut curry granting a powerful foraging boost, learned on Ginger Island and loved by Caroline and Gus alike.","image":"https://stardewvalleywiki.com/mediawiki/images/3/32/Tropical_Curry.png"},{"name":"Squid Ink Ravioli","rarity":"epic","id":"squid-ink-ravioli","subtitle":"Cooking & Food","details":"Bug meat and squid ink pasta granting a mining boost and a brief shield from harm, taught by the island's dwarf in the volcano.","image":"https://stardewvalleywiki.com/mediawiki/images/8/86/Squid_Ink_Ravioli.png"},{"name":"Complete Breakfast","rarity":"rare","id":"complete-breakfast","subtitle":"Cooking & Food","details":"Hearty plate of egg, milk, hashbrowns, and pancakes granting farming skill and extra energy, fit for the longest harvest day.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3d/Complete_Breakfast.png"},{"name":"Pink Cake","rarity":"rare","id":"pink-cake","subtitle":"Cooking & Food","details":"Melon, wheat flour, sugar, and egg cake of celebration, loved by Haley, Jas, and Vincent and baked pink for birthdays.","image":"https://stardewvalleywiki.com/mediawiki/images/3/32/Pink_Cake.png"},{"name":"Chocolate Cake","rarity":"rare","id":"chocolate-cake","subtitle":"Cooking & Food","details":"Wheat flour, sugar, and egg cake loved by Abigail and Jodi, simple to bake and impossible to keep on a farmhouse counter.","image":"https://stardewvalleywiki.com/mediawiki/images/8/87/Chocolate_Cake.png"},{"name":"Lobster Bisque","rarity":"rare","id":"lobster-bisque","subtitle":"Cooking & Food","details":"Willy's family soup of lobster and milk granting strong fishing and extra energy, for nights chasing the hardest catches.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0a/Lobster_Bisque.png"},{"name":"Crab Cakes","rarity":"rare","id":"crab-cakes","subtitle":"Cooking & Food","details":"Crab, wheat flour, egg, and oil cakes granting speed and defence, served at the saloon and loved by Elliott for coastal flavour.","image":"https://stardewvalleywiki.com/mediawiki/images/7/70/Crab_Cakes.png"},{"name":"Farmer's Lunch","rarity":"uncommon","id":"farmers-lunch","subtitle":"Cooking & Food","details":"Omelet and parsnip lunch granting a strong farming boost, packed by a farmer for a farmer at the height of the season.","image":"https://stardewvalleywiki.com/mediawiki/images/7/79/Farmer%27s_Lunch.png"},{"name":"Survival Burger","rarity":"uncommon","id":"survival-burger","subtitle":"Cooking & Food","details":"Bread, cave carrot, and eggplant burger granting a foraging boost, taught by survival skill and loved by Emily above all.","image":"https://stardewvalleywiki.com/mediawiki/images/8/87/Survival_Burger.png"},{"name":"Dish O' The Sea","rarity":"uncommon","id":"dish-o-the-sea","subtitle":"Cooking & Food","details":"Sardines and hashbrowns granting a strong fishing boost, taught by Willy for anglers who eat before they cast.","image":"https://stardewvalleywiki.com/mediawiki/images/f/ff/Dish_O%27_The_Sea.png"},{"name":"Miner's Treat","rarity":"uncommon","id":"miners-treat","subtitle":"Cooking & Food","details":"Cave carrot, sugar, and milk treat granting a strong mining boost, sweet enough to keep a delver swinging all afternoon.","image":"https://stardewvalleywiki.com/mediawiki/images/1/12/Miner%27s_Treat.png"},{"name":"Roots Platter","rarity":"uncommon","id":"roots-platter","subtitle":"Cooking & Food","details":"Cave carrot and winter root platter granting a powerful attack boost, taught through combat for deep and dangerous floors.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e0/Roots_Platter.png"},{"name":"Pepper Poppers","rarity":"uncommon","id":"pepper-poppers","subtitle":"Cooking & Food","details":"Hot pepper and cheese poppers granting farming skill and speed, mailed by Shane and loved by both Shane and Maru.","image":"https://stardewvalleywiki.com/mediawiki/images/0/08/Pepper_Poppers.png"},{"name":"Spicy Eel","rarity":"uncommon","id":"spicy-eel","subtitle":"Cooking & Food","details":"Eel and hot pepper dish granting luck and speed, taught by George, dropped by serpents, and loved fiercely by Abigail.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f2/Spicy_Eel.png"},{"name":"Banana Pudding","rarity":"uncommon","id":"banana-pudding","subtitle":"Cooking & Food","details":"Banana, milk, sugar, and rice pudding from the island trader, granting mining, luck, and defence in one tropical bowl.","image":"https://stardewvalleywiki.com/mediawiki/images/4/40/Banana_Pudding.png"},{"name":"Mango Sticky Rice","rarity":"uncommon","id":"mango-sticky-rice","subtitle":"Cooking & Food","details":"Mango and coconut rice granting strong defence, taught by Leo after island friendship and served warm with island fruit.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6e/Mango_Sticky_Rice.png"},{"name":"Poi","rarity":"uncommon","id":"poi","subtitle":"Cooking & Food","details":"Simple taro dish taught by Leo, plain, filling, and loved by Leo himself as a taste of Ginger Island home cooking.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Poi.png"},{"name":"Ginger Ale","rarity":"uncommon","id":"ginger-ale","subtitle":"Cooking & Food","details":"Ginger and sugar soda granting a touch of luck, bought and learned around Ginger Island for bright, bubbly good fortune.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1a/Ginger_Ale.png"},{"name":"Ice Cream","rarity":"uncommon","id":"ice-cream","subtitle":"Cooking & Food","details":"Sweet summer treat sold from Alex's stand and loved across town, simple, cold, and perfect after a morning on the beach.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5d/Ice_Cream.png"},{"name":"Fried Egg","rarity":"common","id":"fried-egg","subtitle":"Cooking & Food","details":"The first dish most farmers cook, a single egg in a pan, restoring modest energy and starting a lifelong kitchen habit.","image":"https://stardewvalleywiki.com/mediawiki/images/1/18/Fried_Egg.png"},{"name":"Omelet","rarity":"common","id":"omelet","subtitle":"Cooking & Food","details":"Egg and milk omelet taught by the Queen of Sauce, folded into complete breakfasts and farmer's lunches across the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/1/12/Omelet.png"},{"name":"Salad","rarity":"common","id":"salad","subtitle":"Cooking & Food","details":"Leek, dandelion, and vinegar salad taught by Emily, loved by Leah, and as close as cooking gets to a walk in spring.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7e/Salad.png"},{"name":"Cheese Cauliflower","rarity":"common","id":"cheese-cauliflower","subtitle":"Cooking & Food","details":"Cauliflower and cheese bake mailed by Pam, loved by Maru, and proof that a spring crop improves with a hot oven.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6e/Cheese_Cauliflower.png"},{"name":"Baked Fish","rarity":"common","id":"baked-fish","subtitle":"Cooking & Food","details":"Sunfish, bream, and wheat flour supper that turns two humble river fish into a proper plated meal for the farmhouse.","image":"https://stardewvalleywiki.com/mediawiki/images/9/94/Baked_Fish.png"},{"name":"Parsnip Soup","rarity":"common","id":"parsnip-soup","subtitle":"Cooking & Food","details":"Parsnip, milk, and vinegar soup mailed by Caroline at spring friendship, gentle, warm, and made for new farmers.","image":"https://stardewvalleywiki.com/mediawiki/images/7/76/Parsnip_Soup.png"},{"name":"Vegetable Medley","rarity":"common","id":"vegetable-medley","subtitle":"Cooking & Food","details":"Tomato and beet medley mailed through friendship, loved by many villagers, and colourful enough for any fall table.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0a/Vegetable_Medley.png"},{"name":"Pancakes","rarity":"common","id":"pancakes","subtitle":"Cooking & Food","details":"Wheat flour and egg pancakes granting a foraging boost, flipped for breakfasts loved from the farmhouse to the saloon.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6b/Pancakes.png"},{"name":"Hashbrowns","rarity":"common","id":"hashbrowns","subtitle":"Cooking & Food","details":"Potato and oil hashbrowns granting a farming boost, crisped in a pan and folded into complete breakfasts and farm lunches.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8f/Hashbrowns.png"},{"name":"Pizza","rarity":"common","id":"pizza","subtitle":"Cooking & Food","details":"Wheat flour, tomato, and cheese favourite of Sam and Shane, sold at the saloon and baked at home for easy loved gifts.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f4/Pizza.png"},{"name":"Spaghetti","rarity":"common","id":"spaghetti","subtitle":"Cooking & Food","details":"Wheat flour and tomato pasta sold at the saloon, simple to cook, and a dependable gift for villagers who love Italian food.","image":"https://stardewvalleywiki.com/mediawiki/images/0/08/Spaghetti.png"},{"name":"Maki Roll","rarity":"common","id":"maki-roll","subtitle":"Cooking & Food","details":"Fish, seaweed, and rice roll taught through fishing skill, neat, portable, and made from almost any fish in the creel.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b6/Maki_Roll.png"},{"name":"Sashimi","rarity":"common","id":"sashimi","subtitle":"Cooking & Food","details":"Any fish sliced raw into a clean, rich dish taught by Linus, loved by Sebastian, and only as good as its fish.","image":"https://stardewvalleywiki.com/mediawiki/images/4/41/Sashimi.png"},{"name":"Tortilla","rarity":"common","id":"tortilla","subtitle":"Cooking & Food","details":"Corn pressed flat in a pan, the base for quesadillas and burritos and a gift that travels well across the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d7/Tortilla.png"},{"name":"Fruit Salad","rarity":"common","id":"fruit-salad","subtitle":"Cooking & Food","details":"Blueberry, melon, and apricot salad from the Queen of Sauce, loved by Haley and bright with summer orchard fruit.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9e/Fruit_Salad.png"},{"name":"Maple Bar","rarity":"common","id":"maple-bar","subtitle":"Cooking & Food","details":"Maple syrup, sugar, and wheat flour bar loved by Sam, granting farming, fishing, and foraging in one sticky square.","image":"https://stardewvalleywiki.com/mediawiki/images/1/18/Maple_Bar.png"}]});
